TRUNCATE pf_redemption_log, pf_sessions, pf_hotspot_users, pf_vouchers, pf_sites, pf_customers CASCADE;
-- AAA identity written at ISSUE, exactly as VoucherService::issue() does today.
SELECT v.id, v.customer_id, c.radius_ref||'-'||replace(v.code,'-','')
  FROM pf_vouchers v JOIN pf_customers c ON c.id = v.customer_id;
TRUNCATE pf_auth_sessions;
